<?php $er = fn($k) => $errors[$k] ?? ''; $v = fn($k) => $s[$k] ?? ''; ?>
<div class="be_page"><div class="be_pagehead"><h1><?= e(t('set.section')) ?></h1></div><div class="be_card"><?= errors_summary($errors) ?>
<form class="cmp_form be_form" method="post" action="<?= e(url('content', 'section', !empty($s['id']) ? [$s['id']] : [])) ?>"><?= csrf_field() ?><div class="fields">
<?= field(t('set.title'), 'title', $v('title'), ['required' => true, 'maxlength' => 255, 'error' => $er('title')]) ?><?= field(t('set.abbrev'), 'abbrev', $v('abbrev'), ['maxlength' => 30]) ?>
<?= field(t('set.policy'), 'policy', $v('policy'), ['type' => 'textarea', 'rows' => 4]) ?><?= field(t('set.word_count'), 'word_count', $v('word_count'), ['maxlength' => 6, 'error' => $er('word_count'), 'help' => t('set.word_count_help')]) ?>
<?= checkbox('abstracts_required', e(t('set.abstracts_required')), !empty($s['abstracts_required'])) ?><?= checkbox('editor_restricted', e(t('set.editor_restricted')), !empty($s['editor_restricted'])) ?><?= checkbox('meta_reviewed', e(t('set.meta_reviewed')), !empty($s['meta_reviewed'])) ?>
<fieldset class="be_fs"><legend><?= e(t('set.section_editors')) ?></legend><?php foreach ($editors as $e_): ?><div class="optin"><label><input type="checkbox" name="editors[]" value="<?= (int)$e_['id'] ?>"<?= in_array((int)$e_['id'], $chosen, true) ? ' checked' : '' ?>> <?= e(trim($e_['given_name'] . ' ' . $e_['family_name'])) ?></label></div><?php endforeach; ?><?php if (!$editors): ?><p class="muted"><?= e(t('set.none')) ?></p><?php endif; ?></fieldset>
</div><div class="buttons"><button class="submit" type="submit"><?= e(t('wizard.save')) ?></button><a href="<?= e(url('settings', 'index', ['journal', 'sections'])) ?>"><?= e(t('wizard.cancel')) ?></a></div></form></div></div>
